# Applies checked exact-source edits to pinned Lab 62. No title files.
import json, pathlib
edits = json.loads("{\n  \"crates/victory-hle/src/modules/dstorage.rs\": [\n    [\n      \"reads: VecDeque<(u64, Request)>,\",\n      \"reads: VecDeque<(u64, QueuedRead)>,\"\n    ],\n    [\n      \"    request: Request,\\n    staging: u64,\",\n      \"    request: Request,\\n    enqueued: Option<Vec<usize>>,\\n    staging: u64,\"\n    ],\n    [\n      \"let result = execute(&job.request);\",\n      \"let result = execute(&job.request, job.enqueued.as_deref());\"\n    ],\n    [\n      \"        let &(seq, request) = lane.reads.front()?;\\n        let staging = staging_bytes(&request);\",\n      \"        let (_, queued) = lane.reads.front()?;\\n        let staging = staging_bytes(&queued.request);\"\n    ],\n    [\n      \"        lane.reads.pop_front();\\n        lane.running.insert(seq);\",\n      \"        let (seq, queued) = lane.reads.pop_front()?;\\n        let QueuedRead { request, enqueued } = queued;\\n        lane.running.insert(seq);\"\n    ],\n    [\n      \"            request,\\n            staging,\\n        })\",\n      \"            request,\\n            enqueued,\\n            staging,\\n        })\"\n    ],\n    [\n      \"enum Command {\\n    Read(Request),\",\n      \"struct QueuedRead {\\n    request: Request,\\n    enqueued: Option<Vec<usize>>,\\n}\\n\\nenum Command {\\n    Read(QueuedRead),\"\n    ],\n    [\n      \"    as_enqueued(&request);\\n    queue(this, Command::Read(request));\",\n      \"    let enqueued = as_enqueued(&request);\\n    queue(this, Command::Read(QueuedRead { request, enqueued }));\"\n    ],\n    [\n      \"fn execute(request: &Request) -> Result<(), HRESULT> {\",\n      \"fn execute(request: &Request, enqueued: Option<&[usize]>) -> Result<(), HRESULT> {\"\n    ],\n    [\n      \"return into_destination(request, size, |out| {\",\n      \"return into_destination(request, size, enqueued, |out| {\"\n    ],\n    [\n      \"into_destination(request, size, |out| match tables {\",\n      \"into_destination(request, size, enqueued, |out| match tables {\"\n    ],\n    [\n      \"    len: usize,\\n    fill: impl FnOnce(&mut [u8]) -> Result<usize, HRESULT>,\",\n      \"    len: usize,\\n    enqueued: Option<&[usize]>,\\n    fill: impl FnOnce(&mut [u8]) -> Result<usize, HRESULT>,\"\n    ],\n    [\n      \"    let pages = &filled(request.destination.cast(), (offset + len).div_ceil(PAGE))[..];\",\n      \"    let page_numbers = filled(request.destination.cast(), (offset + len).div_ceil(PAGE), enqueued);\\n    if page_numbers.contains(&0) {\\n        tracing::warn!(len, \\\"stability: refusing incomplete DirectStorage page array\\\");\\n        return Err(E_INVALIDARG);\\n    }\\n    let pages = &page_numbers[..];\"\n    ],\n    [\n      \"/// (Neptune) What the page arrays of the requests not yet run held when they were enqueued,\\n/// by the array's address, in the order of the requests ([`as_enqueued`]).\\nstatic ENQUEUED: Mutex<Option<HashMap<usize, VecDeque<Vec<usize>>>>> = Mutex::new(None);\\n\\n\",\n      \"\"\n    ],\n    [\n      \"fn as_enqueued(request: &Request) {\",\n      \"fn as_enqueued(request: &Request) -> Option<Vec<usize>> {\"\n    ],\n    [\n      \"if request.options & PAGE_DESTINATION == 0 || request.destination.is_null() || stale_wait().is_zero() {\\n        return;\\n    }\",\n      \"if request.options & PAGE_DESTINATION == 0 || request.destination.is_null() || stale_wait().is_zero() {\\n        return None;\\n    }\"\n    ],\n    [\n      \"    let now: Vec<usize> = (0..n).map(|i| unsafe { array.add(i).read_volatile() }).collect();\\n    let mut all = ENQUEUED.lock().unwrap_or_else(|e| e.into_inner());\\n    all.get_or_insert_with(HashMap::new).entry(array as usize).or_default().push_back(now);\",\n      \"    Some((0..n).map(|i| unsafe { array.add(i).read_volatile() }).collect())\"\n    ],\n    [\n      \"fn filled(array: *const usize, n: usize) -> Vec<usize> {\",\n      \"fn filled(array: *const usize, n: usize, before: Option<&[usize]>) -> Vec<usize> {\"\n    ],\n    [\n      \"    let before = {\\n        let mut all = ENQUEUED.lock().unwrap_or_else(|e| e.into_inner());\\n        all.as_mut().and_then(|all| {\\n            let line = all.get_mut(&(array as usize))?;\\n            let before = line.pop_front();\\n            if line.is_empty() {\\n                all.remove(&(array as usize));\\n            }\\n            before\\n        })\\n    };\\n\",\n      \"\"\n    ],\n    [\n      \"assert_eq!(filled(array.as_ptr().cast(), 2), [7, 8]);\",\n      \"assert_eq!(filled(array.as_ptr().cast(), 2, None), [7, 8]);\"\n    ],\n    [\n      \"assert_eq!(filled(array.as_ptr().cast(), 2), [0, 8]);\",\n      \"assert_eq!(filled(array.as_ptr().cast(), 2, None), [0, 8]);\"\n    ],\n    [\n      \"lane.unsubmitted.push(Command::Read(r));\",\n      \"lane.unsubmitted.push(Command::Read(QueuedRead { request: r, enqueued: None }));\"\n    ],\n    [\n      \"        let workers = std::thread::available_parallelism().map_or(4, |n| n.get());\",\n      \"        let available = std::thread::available_parallelism().map_or(4, |n| n.get());\\n        let workers = std::env::var(\\\"VICTORY_DSTORAGE_WORKERS\\\").ok().and_then(|v| v.parse::<usize>().ok()).map_or(available, |n| n.clamp(1, available));\"\n    ],\n    [\n      \"    let buffered = request.options & (ZLIB | BCPACK | PAGE_DESTINATION) != 0;\\n    if buffered && request.options & MEMORY_SOURCE == 0 {\\n        u64::from(request.source_size)\\n    } else {\\n        0\\n    }\",\n      \"    // Conservative accounting: include decompression and bounce scratch, not just compressed input.\\n    let source = if request.options & MEMORY_SOURCE == 0 { u64::from(request.source_size) } else { 0 };\\n    let destination = if request.options & (ZLIB | BCPACK | PAGE_DESTINATION) != 0 { u64::from(request.destination_size) } else { 0 };\\n    let intermediate = if request.options & ZLIB != 0 && request.options & BCPACK != 0 { u64::from(request.intermediate_size) } else { 0 };\\n    source + destination + intermediate\"\n    ],\n    [\n      \"/// Staging bytes a request holds while it runs: what it buffers between\\n/// the file and the destination. Raw reads go straight to their\\n/// destination, memory sources need none (as on the console).\",\n      \"/// Conservative scratch budget: file input, possible destination bounce,\\n/// and intermediate compressed data. In-place writes may use less.\"\n    ],\n    [\n      \"fn staging_bounds_compressed_bytes_in_flight() {\\n        let mut l = lanes(100);\",\n      \"fn staging_bounds_compressed_bytes_in_flight() {\\n        let mut l = lanes(200);\"\n    ],\n    [\n      \"read(&mut l, 0, 0, 1000); // raw: straight to its destination\",\n      \"read(&mut l, 0, MEMORY_SOURCE, 1000); // raw memory: straight to destination\"\n    ],\n    [\n      \"assert!(l.start().is_none(), \\\"60 + 60 > 100\\\");\",\n      \"assert!(l.start().is_none(), \\\"120 + 120 > 200\\\");\"\n    ],\n    [\n      \"assert_eq!((second.staging, raw.staging), (60, 0));\",\n      \"assert_eq!((second.staging, raw.staging), (120, 0));\"\n    ],\n    [\n      \"    #[test]\\n    fn priorities_share_by_bytes_about_tenfold() {\",\n      \"    #[test]\\n    fn snapshot_follows_its_request_across_priority_lanes() {\\n        let mut l = lanes(STAGING);\\n        l.lanes.insert(0, Lane::new(0, 64));\\n        l.lanes.insert(1, Lane::new(1, 64));\\n        let r = request(PAGE_DESTINATION, std::ptr::null_mut(), 0, std::ptr::null(), 0, 0);\\n        l.lanes.get_mut(&0).unwrap().unsubmitted.push(Command::Read(QueuedRead { request: r, enqueued: Some(vec![11]) }));\\n        l.lanes.get_mut(&1).unwrap().unsubmitted.push(Command::Read(QueuedRead { request: r, enqueued: Some(vec![22]) }));\\n        l.submit(0);\\n        l.submit(1);\\n        let a = l.start().unwrap();\\n        let b = l.start().unwrap();\\n        for job in [a, b] {\\n            assert_eq!(job.enqueued.as_deref(), Some(if job.lane == 0 { &[11usize][..] } else { &[22usize][..] }));\\n        }\\n    }\\n\\n    #[test]\\n    fn priorities_share_by_bytes_about_tenfold() {\"\n    ]\n  ],\n  \"crates/victory-loader/src/crash.rs\": [\n    [\n      \"    unsafe { report(\\\"unhandled exception\\\", info, true) };\\n}\",\n      \"    unsafe { report(\\\"unhandled exception\\\", info, true) };\\n    // Only after an unhandled access violation, never on a first-chance exception.\\n    if std::env::var_os(\\\"VICTORY_FATAL_EXIT\\\").is_some_and(|v| v == \\\"1\\\") {\\n        // SAFETY: the OS supplied the exception record. Terminate only our own process.\\n        unsafe {\\n            if !info.is_null() && !(*info).ExceptionRecord.is_null()\\n                && (*(*info).ExceptionRecord).ExceptionCode == EXCEPTION_ACCESS_VIOLATION\\n            {\\n                use windows_sys::Win32::System::Threading::{GetCurrentProcess, TerminateProcess};\\n                TerminateProcess(GetCurrentProcess(), EXCEPTION_ACCESS_VIOLATION as u32);\\n            }\\n        }\\n    }\\n}\"\n    ]\n  ],\n  \"play.ps1\": [\n    [\n      \"  [switch]$LowMemory\\n)\",\n      \"  [switch]$LowMemory,\\n  [switch]$RefreshWrites,\\n  [switch]$NoSlotEviction,\\n  [switch]$KeepCrashReporter\\n)\"\n    ],\n    [\n      \"VICTORY_CARD_WINDOWS_MB = '4096'\",\n      \"VICTORY_CARD_WINDOWS_MB = '3072'\"\n    ],\n    [\n      \"VICTORY_TEXTURE_STAGE_MB = '512'\",\n      \"VICTORY_TEXTURE_STAGE_MB = '256'\"\n    ],\n    [\n      \"VICTORY_LIST_POOL_MOST = '2048'; VICTORY_LIST_POOL_MB = '2048'\",\n      \"VICTORY_LIST_POOL_MOST = '1024'; VICTORY_LIST_POOL_MB = '512'; VICTORY_LIST_POOL_IDLE_S = '5'\"\n    ],\n    [\n      \"VICTORY_STAGE_POOL_MB = '2048'\",\n      \"VICTORY_STAGE_POOL_MB = '512'\"\n    ],\n    [\n      \"VICTORY_VRAM_IDLE_MS = '15000,2500,1000'\",\n      \"VICTORY_VRAM_IDLE_MS = '5000,2000,1000'\"\n    ],\n    [\n      \"  VICTORY_TEXTURE_MAX_DIM = '1024'; VICTORY_LIBRARY_LOCK = '0'\",\n      \"  VICTORY_TEXTURE_MAX_DIM = '1024'; VICTORY_LIBRARY_LOCK = '0'\\n  VICTORY_TEXTURE_ROOM_PERCENT = '80'; VICTORY_VRAM_EVICT = '80'\\n  VICTORY_TEXTURE_LRU = '1'; VICTORY_TEXTURE_KEEP_PERCENT = '75'\\n  VICTORY_SLOT_EVICT = '1'; VICTORY_SLOT_EVICT_PERCENT = '82'; VICTORY_SLOT_EVICT_MB = '256'\\n  VICTORY_DSTORAGE_WORKERS = '8'; VICTORY_PROCESS_PRIORITY = 'normal'; VICTORY_FATAL_EXIT = '1'\"\n    ],\n    [\n      \"if ($LowMemory) { $set['VICTORY_TEXTURE_MAX_DIM'] = '512' }\",\n      \"if ($LowMemory) { $set['VICTORY_TEXTURE_MAX_DIM'] = '512' }\\nif ($RefreshWrites) { $set['VICTORY_PAGE_WRITES'] = 'all' }\\nif ($NoSlotEviction) { $set['VICTORY_SLOT_EVICT'] = '0' }\\nif ($KeepCrashReporter) { $set['VICTORY_FATAL_EXIT'] = '0' }\"\n    ],\n    [\n      \"  for ($i = 1; $i -le 120; $i++) {\\n    & $victory translate --cache --pipelines --jobs 8 $shaders\\n    if ($LASTEXITCODE -eq 0) { \\\"Pre-build done ($i pass(es)). Now run .\\\\play.ps1\\\"; exit 0 }\\n    \\\"Pass $i ended with code $LASTEXITCODE (driver crash?): resuming...\\\"\\n    Start-Sleep 5\\n  }\\n  throw 'Pre-build did not finish after 120 passes'\",\n      \"  & $victory translate --cache --pipelines --jobs 8 $shaders\\n  if ($LASTEXITCODE -ne 0) { throw \\\"Pre-build failed ($LASTEXITCODE); no automatic retry\\\" }\\n  'Pre-build done. Now run .\\\\play.ps1'\\n  return\"\n    ],\n    [\n      \"& $victory run $Exe --execute @console\",\n      \"$ErrorActionPreference = 'Continue'\\n& $victory run $Exe --execute @console\\n$code = $LASTEXITCODE\\nWrite-Host \\\"Victory exited: $code\\\"\\nexit $code\"\n    ]\n  ]\n}")
for name, changes in edits.items():
    path = pathlib.Path(name)
    data = path.read_text(encoding="utf-8")
    for old,new in changes:
        if data.count(old) != 1:
            raise RuntimeError(f"Unexpected source anchor in {name}: {old[:100]}")
        data = data.replace(old,new,1)
    path.write_text(data,encoding="utf-8",newline="\n")
    print(f"{name}: {len(changes)} verified edits")
